#ifndef ZOVUTILS_DATE_BACKEND_H
#define ZOVUTILS_DATE_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <sys/stat.h>
static inline int zov_date_run(int argc,char**argv){int utc=0;const char*datearg=NULL,*ref=NULL,*fmt=NULL;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: date [OPTION]... [+FORMAT]\nDisplay the current time in the given FORMAT.\n  -u, --utc, --universal  print or set Coordinated Universal Time (UTC)\n  -d, --date=STRING       display time described by STRING, not now\n  -r, --reference=FILE    display the last modification time of FILE\n      --help              display this help and exit\n      --version           output version information and exit");return 0;}if(!strcmp(a,"--version")){puts("date (zovutils) 0.10.4");return 0;}if(!strcmp(a,"-u")||!strcmp(a,"--utc")||!strcmp(a,"--universal")){utc=1;continue;}if(!strcmp(a,"-d")||!strcmp(a,"--date")){if(i+1>=argc){fprintf(stderr,"date: option requires an argument -- 'd'\n");return 1;}datearg=argv[++i];continue;}if(!strncmp(a,"--date=",7)){datearg=a+7;continue;}if(!strcmp(a,"-r")||!strcmp(a,"--reference")){if(i+1>=argc){fprintf(stderr,"date: option requires an argument -- 'r'\n");return 1;}ref=argv[++i];continue;}if(!strncmp(a,"--reference=",12)){ref=a+12;continue;}if(a[0]=='+'){if(fmt){fprintf(stderr,"date: multiple output formats specified\n");return 1;}fmt=a+1;continue;}if(a[0]=='-'&&a[1]){fprintf(stderr,"date: unrecognized option '%s'\nTry 'date --help' for more information.\n",a);return 1;}fprintf(stderr,"date: extra operand '%s'\nTry 'date --help' for more information.\n",a);return 1;}time_t t=time(NULL);if(ref){struct stat st;if(stat(ref,&st)){fprintf(stderr,"date: %s: %s\n",ref,strerror(errno));return 1;}t=st.st_mtime;}if(datearg){if(datearg[0]=='@'){char*e;errno=0;long long sec=strtoll(datearg+1,&e,10);if(errno||*e){fprintf(stderr,"date: invalid date '%s'\n",datearg);return 1;}t=(time_t)sec;}else{fprintf(stderr,"date: invalid date '%s'\n",datearg);return 1;}}struct tm tmv;struct tm*pt=utc?gmtime_r(&t,&tmv):localtime_r(&t,&tmv);if(!pt){fprintf(stderr,"date: cannot represent the date\n");return 1;}const char*format=fmt?fmt:"%a %b %e %H:%M:%S %Z %Y";char out[8192];size_t n=strftime(out,sizeof(out),format,pt);if(!n&&*format){fprintf(stderr,"date: format string is too long\n");return 1;}puts(out);return 0;}
#endif
